// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address nonCreator) public {
        vm.assume(nonCreator != address(this) && nonCreator != address(c));
        vm.deal(nonCreator, 1 ether);
        vm.prank(nonCreator);
        bool ok;
        try c.migrateTo(address(0)) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
